const body = $json.body ?? $json;
const text = String(body.text || '').trim();
const lead = body.lead ?? {};
const email = String(lead.email || body.email || '').trim().toLowerCase();
const name = String(lead.name || body.name || '').trim();
const company = String(lead.company || body.company || '').trim();
const channels = Array.isArray(body.channels) ? body.channels.map(value => String(value).toLowerCase()) : [];
const monthlyContacts = Number(body.monthlyContacts || lead.monthlyContacts || 0);
const whatsappUrl = body.whatsappUrl || 'https://wa.me/59899576144?text=Hola%2C%20quiero%20una%20demo%20del%20servicio%20de%20notificaciones.';

const normalize = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const query = normalize(text);

const useCases = [
  { key: 'ecommerce', label: 'ecommerce', terms: ['tienda', 'ecommerce', 'shopify', 'woocommerce', 'pedido', 'carrito'] },
  { key: 'operations', label: 'operaciones', terms: ['operacion', 'operaciones', 'logistica', 'entrega', 'reparto', 'turnos'] },
  { key: 'collections', label: 'cobranzas', terms: ['cobranza', 'cobranzas', 'pago', 'vencimiento', 'deuda', 'recordatorio'] },
  { key: 'alerts', label: 'alertas internas', terms: ['alerta', 'incidente', 'caida', 'sistema', 'monitoreo', 'devops'] },
  { key: 'marketing', label: 'marketing automatizado', terms: ['marketing', 'campana', 'campana', 'promocion', 'promo', 'newsletter'] }
];

const matchedUseCase = useCases.find(entry => entry.terms.some(term => query.includes(normalize(term))));
const channelScore = channels.length || (/whatsapp|email|sms|push/.test(query) ? 2 : 1);
const sizeScore = monthlyContacts >= 50000 ? 3 : monthlyContacts >= 10000 ? 2 : monthlyContacts > 0 ? 1 : 0;
const urgencyScore = /urgente|ya|hoy|esta semana|cuanto antes/.test(query) ? 2 : 0;
const score = channelScore + sizeScore + urgencyScore;

const plans = [
  { key: 'starter', label: 'Starter', price: 'USD 149/mes', fit: 'equipos chicos con una automatizacion principal y hasta 2 canales' },
  { key: 'growth', label: 'Growth', price: 'USD 349/mes', fit: 'operaciones comerciales con varios flujos, CRM y mensajes transaccionales' },
  { key: 'scale', label: 'Scale', price: 'USD 790/mes', fit: 'volumen alto, varios sistemas y observabilidad completa' }
];

const recommendedPlan = score >= 5 ? plans[2] : score >= 3 ? plans[1] : plans[0];
const useCaseLabel = matchedUseCase ? matchedUseCase.label : 'notificaciones automatizadas';

let reply = '';
let next_actions = [
  { label: 'Pedir demo', prompt: 'Quiero una demo del servicio de notificaciones' },
  { label: 'Ver plan recomendado', prompt: 'Que plan me recomendas para mi operacion?' },
  { label: 'WhatsApp', type: 'url', url: whatsappUrl }
];

if (!email) {
  return [{ json: { success: false, requires_email: true, reply: 'Antes de seguir necesito tu email para enviarte una propuesta y registrar la oportunidad.', plan: null, use_case: useCaseLabel, next_actions, whatsapp_url: whatsappUrl } }];
}

if (!text) {
  reply = `Puedo ayudarte a vender notificaciones por WhatsApp, email, SMS o alertas internas. Para ${useCaseLabel}, el mejor punto de partida hoy es ${recommendedPlan.label}.`;
} else if (/precio|plan|cuanto cuesta|costa/.test(query)) {
  reply = `Para ${useCaseLabel}, te recomiendo ${recommendedPlan.label} (${recommendedPlan.price}). Encaja bien en ${recommendedPlan.fit}.`;
} else if (/demo|reunion|llamada/.test(query)) {
  reply = `Perfecto. Para ${company || 'tu equipo'}, la demo conviene enfocarla en ${useCaseLabel} con ${channels.length ? channels.join(', ') : 'los canales que hoy esten evaluando'}.`;
  next_actions = [
    { label: 'Seguir por WhatsApp', type: 'url', url: whatsappUrl },
    { label: 'Enviar propuesta', prompt: 'Quiero una propuesta comercial' },
    { label: 'Ver integraciones', prompt: 'Que integraciones soportan?' }
  ];
} else if (/integracion|integraciones|n8n|api|webhook/.test(query)) {
  reply = 'El servicio puede montarse sobre n8n, webhooks, CRMs, e-commerce y herramientas internas. La clave es definir eventos, canales y reglas de entrega.';
} else {
  reply = `Veo una oportunidad clara para ${useCaseLabel}. Para ${company || 'tu negocio'}, hoy priorizaria ${recommendedPlan.label} porque permite activar notificaciones utiles sin sobreingenieria.`;
}

const staticData = $getWorkflowStaticData('global');
staticData.leads = Array.isArray(staticData.leads) ? staticData.leads : [];
staticData.leads.unshift({
  created_at: new Date().toISOString(),
  lead: { name, email, company },
  text,
  channels,
  monthly_contacts: monthlyContacts,
  use_case: useCaseLabel,
  recommended_plan: recommendedPlan,
  score
});
staticData.leads = staticData.leads.slice(0, 500);

return [{
  json: {
    success: true,
    requires_email: false,
    reply,
    use_case: useCaseLabel,
    recommended_plan: recommendedPlan,
    next_actions,
    registry_size: staticData.leads.length,
    whatsapp_url: whatsappUrl
  }
}];
